-- Edufy Academy demo courses (idempotent; instructor_id is assigned by scripts/seed-demo.ts)
insert into public.courses (id,slug,title,subtitle,description,category,category_slug,level,price,duration_hours,total_lessons,thumbnail_url,learning_outcomes,prerequisites,target_audience,featured,language,original_price,rating,review_count,bestseller,trending,is_published,is_demo)
select v.*, 'English', v.price, 0, 0, false, false, true, true from (values
('demo-complete-web-development','complete-web-development','Complete Web Development','Build responsive websites from scratch with HTML, CSS and JavaScript.','A structured introduction to building for the web. You will learn semantic HTML, modern CSS layout with Flexbox and Grid, and JavaScript fundamentals, then bring them together to build and publish a responsive multi-page website.','Web Development','web-development','Beginner',999,3,12,'https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=1200&auto=format&fit=crop&q=80','["Write semantic, accessible HTML","Lay out pages with Flexbox and CSS Grid","Add interactivity with JavaScript and the DOM","Publish a responsive website"]'::jsonb,'["A computer with internet access","No prior coding experience required"]'::jsonb,'["Complete beginners","Students starting a tech career","Designers who want to code"]'::jsonb,true),
('demo-full-stack-mern','full-stack-mern','Full Stack MERN Development','Create complete web applications with MongoDB, Express, React and Node.js.','Go from front end to back end. Build a REST API with Node.js and Express, model data in MongoDB, create a React interface, add authentication and deploy a production-ready full-stack application.','Web Development','web-development','Intermediate',1499,3,12,'https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=1200&auto=format&fit=crop&q=80','["Design and build REST APIs with Express","Model data with MongoDB and Mongoose","Build React interfaces with hooks","Implement authentication and deploy"]'::jsonb,'["Comfortable with HTML, CSS and JavaScript basics"]'::jsonb,'["Front-end developers moving to full stack","Graduates preparing for developer roles"]'::jsonb,false),
('demo-ai-fundamentals','ai-fundamentals','Artificial Intelligence Fundamentals','Understand how modern AI works — from machine learning to generative models.','A clear, non-hype introduction to artificial intelligence. Learn core machine-learning ideas, how neural networks are trained, what large language models can and cannot do, and how to think about responsible AI.','Artificial Intelligence','ai-data-science','Beginner',1299,2.3,9,'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1200&auto=format&fit=crop&q=80','["Explain supervised and unsupervised learning","Understand how neural networks learn","Use generative AI tools effectively","Evaluate AI risks and limitations"]'::jsonb,'["Curiosity — no maths background required"]'::jsonb,'["Professionals working alongside AI","Students exploring AI careers"]'::jsonb,true),
('demo-python-masterclass','python-masterclass','Python Programming Masterclass','Learn Python from the ground up and automate everyday tasks.','Master Python step by step: syntax, data structures, functions, files and object-oriented programming. Finish by writing scripts that automate real work such as renaming files, processing spreadsheets and calling web APIs.','Artificial Intelligence','ai-data-science','Beginner',799,2.3,9,'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?w=1200&auto=format&fit=crop&q=80','["Write clean, idiomatic Python","Use lists, dictionaries and sets","Work with files and modules","Automate repetitive tasks"]'::jsonb,'["No programming experience needed"]'::jsonb,'["Beginners learning their first language","Analysts who want to automate work"]'::jsonb,false),
('demo-digital-marketing','digital-marketing','Digital Marketing Masterclass','Plan and run effective campaigns across search, social and email.','Learn how to reach and convert customers online. Cover marketing strategy, SEO, social media, paid advertising, email marketing and analytics, and build a complete campaign plan for a real or sample business.','Business & Leadership','business-leadership','All Levels',999,2.3,9,'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&auto=format&fit=crop&q=80','["Build a digital marketing strategy","Improve search rankings with SEO","Run social and paid campaigns","Measure results with analytics"]'::jsonb,'["No prior marketing experience required"]'::jsonb,'["Small business owners","Marketing beginners","Career switchers"]'::jsonb,false),
('demo-ethical-hacking','ethical-hacking','Ethical Hacking Masterclass','Learn how attackers think so you can defend systems responsibly.','A hands-on introduction to ethical hacking within a legal lab environment. Understand networking, reconnaissance, common web vulnerabilities and how to report and remediate findings professionally.','Cybersecurity','cybersecurity','Intermediate',1499,2.3,9,'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1200&auto=format&fit=crop&q=80','["Set up a safe practice lab","Understand common web vulnerabilities","Perform authorised reconnaissance","Write a professional security report"]'::jsonb,'["Basic networking and command-line familiarity"]'::jsonb,'["IT professionals moving into security","Developers who want to write safer code"]'::jsonb,false),
('demo-ui-ux-figma','ui-ux-figma','UI/UX Design with Figma','Design user-friendly interfaces and interactive prototypes in Figma.','Learn the full design process: user research, information architecture, wireframing, visual design and prototyping. Build a reusable component library and present a polished case study for your portfolio.','UI/UX Design','ui-ux-design','Beginner',899,2.3,9,'https://images.unsplash.com/photo-1561070791-2526d30994b5?w=1200&auto=format&fit=crop&q=80','["Run simple user research","Create wireframes and user flows","Build components and auto layout in Figma","Prototype and present a case study"]'::jsonb,'["A free Figma account"]'::jsonb,'["Aspiring UI/UX designers","Developers and product managers"]'::jsonb,false),
('demo-data-analytics-excel','data-analytics-excel','Data Analytics with Excel','Turn raw data into clear insights with formulas, PivotTables and dashboards.','Become confident with data in Excel. Clean messy datasets, use lookup and logical functions, summarise with PivotTables, visualise trends with charts and build an interactive dashboard for decision-makers.','Artificial Intelligence','ai-data-science','Intermediate',1199,2.3,9,'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&auto=format&fit=crop&q=80','["Clean and prepare data","Use XLOOKUP, IF and aggregation functions","Analyse with PivotTables","Build interactive dashboards"]'::jsonb,'["Microsoft Excel (2019 or Microsoft 365 recommended)"]'::jsonb,'["Business and finance professionals","Aspiring data analysts"]'::jsonb,false),
('demo-wordpress-development','wordpress-development','WordPress Website Development','Build professional websites with WordPress — no coding required.','Create and manage modern websites with WordPress. Set up hosting, choose and customise themes, build pages with the block editor, add essential plugins and launch a fast, secure site.','Web Development','web-development','Beginner',699,2.3,9,'https://images.unsplash.com/photo-1467232004584-a241de8bcf5d?w=1200&auto=format&fit=crop&q=80','["Install and configure WordPress","Customise themes and layouts","Use essential plugins safely","Launch and maintain a website"]'::jsonb,'["No coding experience required"]'::jsonb,'["Small business owners","Freelancers offering website services"]'::jsonb,false),
('demo-freelancing-online-business','freelancing-online-business','Freelancing and Online Business','Start, price and grow a sustainable freelance career online.','A practical guide to working independently. Define your offer, build a portfolio, find clients on platforms and through referrals, price your services, manage projects and handle invoicing and taxes.','Business & Leadership','business-leadership','All Levels',599,2.3,9,'https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=1200&auto=format&fit=crop&q=80','["Define a clear service offering","Build a client-winning portfolio","Price and propose with confidence","Manage clients, projects and payments"]'::jsonb,'["A skill you can offer (design, writing, development, etc.)"]'::jsonb,'["Students and graduates","Professionals planning to go independent"]'::jsonb,false)
) as v(id,slug,title,subtitle,description,category,category_slug,level,price,duration_hours,total_lessons,thumbnail_url,learning_outcomes,prerequisites,target_audience,featured)
on conflict (id) do nothing;

